<script>  String.prototype.trim = function() { return this.replace(/^\s+|\s+$/, ''); }; </script>

<script type="text/javascript">
//alert("i am calling2");
//console.log("script 3 start");
var finaldata;
var storedata= new Promise((resolve, reject) => {
   $.ajax({
       async: true,
       type: "GET",
       url: "https://www.gujaratidating.com/scripts/retail-store.json?v46",
       dataType: "json",
       success: function (response) {
           resolve(response);
            },
            error: function (response) {
                console.log("retail store failed",response);
                reject(response);
            }
    });
});
storedata.then(
  function(value) {
  finaldata=value;
  const statevalue =[];
  for (const key in value) {

    var state = value[key].state;
    statevalue.push({state ,key});

  }

  statevalue.sort((a,b) => (a.state > b.state) ? 1 : ((b.state > a.state) ? -1 : 0));
  const templatechip = document.getElementById("chip-state-li");

    const parentDivchips = document.querySelector(".chipstate");
    for(const  i in statevalue){
    $('#stateVal')
         .append($("<option></option>")
         .attr("value",statevalue[i].key)
         .text(statevalue[i].state));

    const templateInstancechip = document.importNode(templatechip.content, true);
    templateInstancechip.querySelector(".state-name-chip").textContent =statevalue[i].state ;
    templateInstancechip.querySelector(".state-name-chip").setAttribute("id",statevalue[i].key);
       parentDivchips.appendChild(templateInstancechip);
  }
      $('.state-name-chip').on('click', (event)=> {
    const templatechipcity = document.getElementById("chip-city-li");
    const parentDivchipscity = document.querySelector(".chipcity");
    const chipcity = finaldata[event.currentTarget.id];

    while (parentDivchipscity.firstChild) {
            parentDivchipscity.removeChild(parentDivchipscity.firstChild);
    }
    showstatedata(event.currentTarget.id);
    //sorting part start
    const sortcitychips =[];
  for (const key in chipcity) {
    if(chipcity[key].city){
    var city = chipcity[key].city;
    sortcitychips.push({city ,key});
    }
  }

  sortcitychips.sort((a,b) => (a.city > b.city) ? 1 : ((b.city > a.city) ? -1 : 0));
    //sorting part end
    for (  i in sortcitychips)
    {
            var x=sortcitychips[i].key;
      if(chipcity[x].city){
      const templateInstancecity = document.importNode(templatechipcity.content, true);
        templateInstancecity.querySelector(".city-name-chips").textContent = chipcity[x].city;
       // templateInstancecity.querySelector(".city-name-chips").setAttribute("href","#city"+x);
      templateInstancecity.querySelector(".city-name-chips").setAttribute("id","a"+x);
            parentDivchipscity.appendChild(templateInstancecity);
      }
    }


    }  )
  },
  function(error) {}
);
var parentDivstate;
var parentDiv;
document.getElementById("citychip").style.display='block';
function showstatedata(stateID)
{
  const templateState = document.getElementById("my-template");
      parentDivstate = document.querySelector(".state-wise-data");
    const statedata = finaldata[stateID];
    document.getElementById("stateshow").style.display='block';
    document.getElementById("cityshow").style.display='none';

     while (parentDivstate.firstChild) {
             parentDivstate.removeChild(parentDivstate.firstChild);
       }
      $('.state-name')
           .text(statedata.state);

       //sorting part start
    const sortedcity =[];
  for (const key in statedata) {
    if(statedata[key].city){
    var city = statedata[key].city;
    sortedcity.push({city ,key});
    }
  }

  sortedcity.sort((a,b) => (a.city > b.city) ? 1 : ((b.city > a.city) ? -1 : 0));
    //sorting part end


    for (  j in sortedcity)
    {

      var x = sortedcity[j].key;
      var citydata = statedata[x];

       //sorting part start
         const sortedstore =[];
            for (const keytwo in citydata) {
          if(citydata[keytwo].store){
          var store = citydata[keytwo].store;
          sortedstore.push({store ,keytwo});
        }
          }

            sortedstore.sort((a,b) => (a.store > b.store) ? 1 : ((b.store > a.store) ? -1 : 0));
          //sorting part end


      var stateflag = true;
      if(x !='state'){
      for (k in sortedstore){
        var y=sortedstore[k].keytwo;
        let storeLinkURL = getStoreLinkURL(citydata[y].store);
        const templateInstancestate = document.importNode(templateState.content, true);
        if(stateflag && y != 'city'){
            templateInstancestate.querySelector(".city-name-ch").textContent =citydata.city ;
        templateInstancestate.querySelector(".city-name-ch").setAttribute("id","city"+x);
        templateInstancestate.querySelector(".city-name-ch").setAttribute("href",getStoreLinkURL(citydata.city));
            stateflag=false;
              }	
              if(y != 'city'){ 
        templateInstancestate.querySelector(".store-address-ch").textContent =citydata[y].address ;
        if(citydata.city.toLowerCase() !== citydata[y].store.toLowerCase()){
          templateInstancestate.querySelector(".store-name-ch").textContent =citydata[y].store ;
          templateInstancestate.querySelector(".store-name-ch").setAttribute("href", storeLinkURL);
         }
         templateInstancestate.querySelector(".more-info-link").setAttribute("href",storeLinkURL);
        templateInstancestate.querySelector("#StoreImgAtag").setAttribute("href",storeLinkURL);
          templateInstancestate.querySelector(".small-img-ch").setAttribute("src",citydata[y].imageSmall);
          templateInstancestate.querySelector(".small-img-ch").setAttribute("title",citydata[y].store);
          templateInstancestate.querySelector(".small-img-ch").setAttribute("alt",citydata[y].store);
              parentDivstate.appendChild(templateInstancestate);
      }


      }
    }

    }

}

function getStoreLinkURL(storeName){
  //https://www.mobileshopdating.com/gujarati-dating-outlets/ahmedabad.html

  let formattedStoreName = storeName.toLowerCase().replace(/ /g, "-");

  return "https://www.gujaratidating.com/mobileshop-dating-outlets/"+formattedStoreName+".html";
}

function ajaxGetCityListnew(stateid)
{
  var selectstate= finaldata[stateid];
  const sortcity =[];
  for (const key in selectstate) {
    if(selectstate[key].city){
    var city = selectstate[key].city;
    sortcity.push({city ,key});
    }
  }

  sortcity.sort((a,b) => (a.city > b.city) ? 1 : ((b.city > a.city) ? -1 : 0));

  $('#cityVal').empty();
  for(x in sortcity)
  {
    if(sortcity[x].city)
    {
    var city = sortcity[x].city;
    $('#cityVal')
         .append($("<option></option>")
         .attr("value", sortcity[x].key)
         .text(city));
    } 
  }

}

function showAddressnew()
{
  if(document.getElementById("stateVal").value == ""){
      alert("Please Select state value");
      document.getElementById("stateVal").focus();
      return false;
      }else if(document.getElementById("cityVal").value == ""){
      alert("Please Select city value");
      document.getElementById("cityVal").focus();
      return false;
      }else { 
    document.getElementById("stateshow").style.display='none';
    document.getElementById("cityshow").style.display='block';
    var selectedState=document.getElementById("stateVal").value;
    var selectedcity=document.getElementById("cityVal").value;
    var showdata=finaldata[selectedState][selectedcity];
    // Get a reference to the template element
        const template = document.getElementById("my-template");

         // Get a reference to the parent element where you want to append the template instances
         parentDiv = document.querySelector(".new-idea");

    //  while (parentDivstate.firstChild) {
      //        parentDivstate.removeChild(parentDivstate.firstChild);
      //  }
      while (parentDiv.firstChild) {
            parentDiv.removeChild(parentDiv.firstChild);
     }

      //sorting part start
    const dropdowncity =[];
            for (const key in showdata) {
          if(showdata[key].store){
          var store = showdata[key].store;
          dropdowncity.push({store ,key});
        }
          }

            dropdowncity.sort((a,b) => (a.store > b.store) ? 1 : ((b.store > a.store) ? -1 : 0));
          //sorting part end

    // $('.city-name-ch')
        //  .text(showdata.city);
    var flag = true;
    for(x in dropdowncity)
  {   
    var key = dropdowncity[x].key;
    let storeLinkURL = getStoreLinkURL(showdata[key].store);
    const templateInstance = document.importNode(template.content, true);
    if(flag){
    templateInstance.querySelector(".city-name-ch").textContent =showdata.city ;
    templateInstance.querySelector(".city-name-ch").setAttribute("href", getStoreLinkURL(showdata.city));
    flag=false;
    }
    if(key!= 'city'){

    templateInstance.querySelector(".store-address-ch").textContent =showdata[key].address ;
    if(showdata.city.toLowerCase() !== showdata[key].store.toLowerCase()){
    templateInstance.querySelector(".store-name-ch").textContent =showdata[key].store ;
    templateInstance.querySelector(".store-name-ch").setAttribute("href", storeLinkURL);
    }
    templateInstance.querySelector(".more-info-link").setAttribute("href",storeLinkURL);
    templateInstance.querySelector("#StoreImgAtag").setAttribute("href",storeLinkURL);
      templateInstance.querySelector(".small-img-ch").setAttribute("src",showdata[key].imageSmall);
      templateInstance.querySelector(".small-img-ch").setAttribute("title",showdata[key].store);
      templateInstance.querySelector(".small-img-ch").setAttribute("alt",showdata[key].store);

    //    templateInstance.querySelector("p").textContent = itemData.description;

        // Append the populated template instance to the parent div
       parentDiv.appendChild(templateInstance);
  }
  }
}
}
function showTab(tabNo,tabTotal,tabName)
{

  var cur_tab_content = tabName+"_content_"+tabNo;
  if(document.getElementById(cur_tab_content)){
  document.getElementById(cur_tab_content).style.display="block";
  for(i=1;i<=tabTotal;i++)
    {
      if(i != tabNo){
        var oth_tab_content = tabName+"_content_"+i;
        document.getElementById(oth_tab_content).style.display="none";
      }
    }
  }
}
function validatemyphoto(){
var matrid= $('#matriid').val();
if(matrid == 'Dating ID/Mobile Number/E-mail ID' || matrid =="" ){
$('#error').html("<font color='red' size='1'>Enter your Dating ID/Mobile Number/E-mail ID</font>");
return false;
}else{
$('#error').html("");
}
var url="updatephotovalidate.php?";
var postval="matrid="+matrid;
url=url+"&dyn="+Math.random();
$.ajax({
url: url,	
type: 'POST',
data: postval,
success: function (html) { 
  if(html =='success'){
    $('#matriid').val('');
    $.colorbox({html:'Your photo/horoscope will be updated in few minutes',innerWidth:350});
        }
  else if(html =='dberror')
  {
    $('#matriid').val('');
      $.colorbox({html:'We are currently experiencing technical difficulties. Please try again later.',innerWidth:350});
  }
  else if(html =='validated'){

    $('#matriid').val('');
      $('#error').html("<font color='red' size='1'>Not available to validate.</font>");
  }
  else{
    $('#matriid').val('');
      $('#error').html("<font color='red' size='1'>Invalid Dating ID/Mobile Number/E-mail ID. Please try again.</font>");

  }
}
});
}
