<script>
  //console.log("script 6 start");
function interchange(id)
{
  $("ul.chipcity li a").removeClass("highlight");
  // var id= $(this).attr("id");
  $('#'+id).addClass("highlight");

  citylinkthrow(id);


}
function citylinkthrow(value){

var CurrentScrollYValue = window.scrollY;

  if(CurrentScrollYValue < 100){
    window.scrollTo(0, 100);
  }
  var HashName = value.slice(1);
   setTimeout(function () {
     var TargetPositionInfo = $('#city'+HashName).offset();
     //var TargetPositionInfo = $("a[id=" +"city"+ HashName + "]").offset();
     TargetPositionInfo.top -= 70;
     //TargetPositionInfo.behavior = "smooth";
     window.scrollTo({ 
            top :TargetPositionInfo.top ,
      left:TargetPositionInfo.left,
      behavior: "smooth",
    });
     //TargetPositionInfo.behavior = "smooth";
   }, 200);
}
</script>

<!-- Contact toggle menu Section Scripts Start For Mobile Responsive Design -->
<script>
  //console.log("script 7 start");
/* When the user clicks on the button, 
toggle between hiding and showing the dropdown content */
function myFunctionContact() {
  document.getElementById("myDropdownContact").classList.toggle("showcontact");
}

// Close the dropdown if the user clicks outside of it
window.onclick = function(event) {
  if (!event.target.matches('.xs-dropbtn')) {
    var dropdowns = document.getElementsByClassName("xs-dropdown-content");
    var i;
    for (i = 0; i < dropdowns.length; i++) {
      var openDropdown = dropdowns[i];
      if (openDropdown.classList.contains('showcontact')) {
        openDropdown.classList.remove('showcontact');
      }
    }
  }
}
</script>
