                        <p>If you forgot your registered email ID, and mobile number, please reach out to our support team at <a href="mailto:helpdesk@mobileshopdating.com">helpdesk@mobileshopdating.com</a>. They will assist you in the retrieval process and help you regain access to your account. Having at least one of these details is essential for the login process.</p>
                      </div> 

                      <h2 class="acc_trigger">
                          <a href="#" class="w-97">2. How do I log in if I forget my password?</a>
                          <a href="#"class="w-5">
                           <div class="down-arrow"></div>
                          <div class="up-arrow"></div> 
                          </a>
                        </h2>

                      <div class="acc_container">
                        <p>If you forgot your login password or want to change it, follow these steps:</p>
                        <div class="contact-us-listfaq">
                          <ul>
                            <li>Access the Forgot Password link.</li>
                            <li>Enter your mobile number or email ID associated with your account.</li>
                            <li>You will receive a SMS & email ID with a link to reset your password.</li>
                            <li>Follow the link to reset your password securely.</li>
                          </ul>
                        </div>
                      </div>


                      <h2 class="acc_trigger"><a href="#" class="w-97">3. Can I change the mobile number, email address associated with my dating account?</a>
                          <a href="#"class="w-5"> 
                             <div class="down-arrow"></div>
                            <div class="up-arrow"></div> 
                           </a>
                      </h2>

                      <div class="acc_container">
                        <p>Yes, you can change your mobile number or email address.</p>
                        <p style="margin-top:10px;">If you are using your account via app, </p>

                        <div class="contact-us-listfaq">
                          <ul>
                            <li>Go to the <b>"Edit contact"</b> section.</li>
                            <li>Select "Edit contact info" tab.</li>
                            <li>Follow the steps provided to edit your email ID, mobile number, or both.</li>
                          </ul>
                        </div>

                        <p style="margin-top:10px;">If you are using via Web </p>
                        <div class="contact-us-listfaq">
                          <ul>
                            <li>Go to the <b>"Profile settings"</b> -> Privacy -> Mobile Privacy section to change your mobile number.</li>
                            <li>Go to the <b>"Profile settings"</b> -> Edit email address section to change your email address.</li>
                          </ul>
                        </div>
                        <p>Please ensure that these details are accurate as they are essential for login and communication.</p>
                      </div>


                      <h2 class="acc_trigger"><a href="#" class="w-97">4. I didn't receive the OTP for login. What should I do?</a>
                          <a href="#"class="w-5">
