                            <div class="up-arrow"></div> 
                        </a>
                      </h2>

                      <div class="acc_container">
                        <p>If you haven't received the OTP for login, please ensure your mobile number is entered correctly.</p>
                        <p>Also check if your mobile device has a stable network connection, your mobile number is active and capable of receiving SMS.</p>
                        <p>If the issue persists, reach out to our support team at <a href="mailto:helpdesk@mobileshopdating.com">helpdesk@mobileshopdating.com</a> for further assistance.</p>
                      </div>


                      <h2 class="acc_trigger"><a href="#" class="w-97">5. I didn't receive the password reset email. What should I do? </a>
                          <a href="#"class="w-5">
                             <div class="down-arrow"></div>
                            <div class="up-arrow"></div> 
                         </a>
                      </h2>

                      <div class="acc_container">

                        <p>If you haven't received the password reset email, please ensure that your email address is correct. Also, check your spam or junk folders for the email.</p>

                        <p>You can also try requesting another password reset email.</p>

                        <p>If the issue persists, reach out to our support team at <a href="mailto:helpdesk@mobileshopdating.com">helpdesk@mobileshopdating.com</a> for further assistance.</p>

                      </div>


