}
function closed_ticket(status){
  var matriid = 'G6404728';
  if(status == 'closed'){
    var urlpost  = "https://api.mobileshopdating.com/bmcrm/tickets.php?a=getAllTickets&matriid="+matriid+"&ticket_status=closed&count_only=0";
