    var onclicklinkContect = 'Closed Tickets';
        var onclicklink = 0;
  }else{
    var urlpost = '';
    var status_value = '';
  }

  $.ajax({
    url: urlpost,
    type: 'GET',
    dataType :'json',
    success: function (res) {
      var response_data = res['data'];
      var count = response_data['count'];
      var tickets = response_data['tickets'];
      ticket_value = tickets;

      htmlContent = '';
      var conversations = (count == 0) ? 'You have no closed tickets' : count+' conversations';
      htmlContent += '<div style="display: flex;align-items: center;margin-bottom: 20px;"><h2 style="font-size: 16px;font-family: lato;font-weight: bold;">'+status_value+'</h2><span style="padding-left: 8px;font-size: 12px;font-family: lato;color: #000000;margin-top: 2px;">'+conversations+'</span></div>';
      var modal = document.getElementById("myModal");

      for(var i=0;i<count;i++){
        var ticket = tickets[i];
        var ticket_id =ticket['ticket_id'];
        var category = ticket['category'];
        var description = ticket['description'];
        var closed_date = ticket['closed_date'];
        var date_created = ticket['date_created'];
        var read_status = ticket['read_status'];
        var lastNoteDetails = ticket['last_note'];
        var notes_date = ticket['last_note_creation'];

        if(read_status == 0){
          ticket_st = "profile-list active togglechat";
        }else{
          ticket_st = "profile-list in-active togglechat";
        }

        if(closed_date != '-'){
          var dateDetails = closed_date;
        }else{
          var dateDetails = date_created;
        }

        notes_date = (notes_date != '') ? notes_date : dateDetails;

        var aDay = 24*60*60*1000;
        var date = new Date(notes_date); // some mock date
        var milliseconds = date.getTime(); 
        var time_val = time_ago(date);

        htmlContent += ' <div class="d-flex '+ticket_st+'" ><div class="w-3"><img src="https://imgs.mobileshopdating.com/webapp-assets/revamp-images/assisted-service/assisted-logo.svg" alt="logo" style="width:24px;" /></div><div class="w-96 pl-10"><h2 style="font-size: 14px;font-family: lato;font-weight: bold;">Ticket no : '+ticket_id+'</h2><h2 style="font-size: 14px;font-family: lato;font-weight: bold;padding-top:3px;">'+category+'</h2><p  style="font-size: 14px;font-family: lato;padding-top:12px;color: #000;">'+description+'</p><span align="left" style="word-break: break-all;">'+lastNoteDetails+'</span></div><div class="w-13" style="text-align: right;"><p style="font-size: 12px;font-family: lato;">'+time_val+'</p><img src="https://imgs.mobileshopdating.com/bmimgs/contact-revamp/right-arrow.svg" alt="logo" style="width:32px;margin-top:30px;" onclick="ticket_details('+ticket_id+');openChatWindow();"/></div></div>';
      }
      htmlContent +=  '<div class="pt-30"><a href="javascript:void(0)" onclick="closed_ticketnew( '+onclicklink+')"><span style="font-size: 14px;font-family: lato;display: inline-flex;align-items: flex-start;color:#000;">'+onclicklinkContect+' <img src="https://imgs.mobileshopdating.com/bmimgs/contact-revamp/right-arrow-icon-without-circle.svg" alt="logo" style="width:17px;" /> </span></a></div>';
      document.getElementById("ticket_content5").innerHTML = htmlContent;
    }

  });
}
