var filesToUpload = [];  // Array to store files
document.getElementById('attachment').addEventListener('change', handleFileSelect);
document.getElementById('uploadBtn').addEventListener('click', uploadFiles);
function clearAttached(){
  filesToUpload = [];
}
function handleFileSelect(event) 
{
  const files = Array.from(event.target.files); // Convert FileList to array
  const previewContainer = document.getElementById('previewContainer');

  // Add selected files to the array
  filesToUpload = filesToUpload.concat(files);

  // Clear file input to prevent showing file count
  event.target.value = '';

  // Clear previous previews
  previewContainer.innerHTML = '';

  // Display previews
  filesToUpload.forEach((file, index) => {
    const fileReader = new FileReader();
    const fileType = file.type;

    // Create a preview element
    const previewElement = document.createElement('div');
    previewElement.className = 'preview-element';

    if (fileType.startsWith('image/')) {
      fileReader.onload = function(e) {
        const image = document.createElement('img');
        image.src = e.target.result;
        previewElement.appendChild(image);
      };
      fileReader.readAsDataURL(file);
    } else {
      const icon = document.createElement('img');
      icon.src = fileType === 'application/pdf'
        ? 'https://imgs.mobileshopdating.com/bmimgs/contact-revamp/pdf-icon-image.png'
        : 'https://imgs.mobileshopdating.com/bmimgs/contact-revamp/file-icon-image.png'; // Show generic icon for other files
      previewElement.appendChild(icon);
    }

    // Create a remove button
    const removeButton = document.createElement('button');
    removeButton.textContent = 'x';
    removeButton.className = 'remove-button';
    removeButton.addEventListener('click', function() {
      removeFile(index);
    });

    previewElement.appendChild(removeButton);
    previewContainer.appendChild(previewElement);
  });
}
function removeFile(index) 
{
  // Remove the file from the filesToUpload array
  filesToUpload.splice(index, 1);
  // Update previews
  updatePreviews();
}
function updatePreviews() 
{
  const previewContainer = document.getElementById('previewContainer');
  previewContainer.innerHTML = ''; // Clear previews

  filesToUpload.forEach((file, index) => {
    const fileReader = new FileReader();
    const fileType = file.type;

    // Create a preview element
    const previewElement = document.createElement('div');
    previewElement.className = 'preview-element';

    if (fileType.startsWith('image/')) {
      fileReader.onload = function(e) {
        const image = document.createElement('img');
        image.src = e.target.result;
        previewElement.appendChild(image);
      };
      fileReader.readAsDataURL(file);
    } else {
      const icon = document.createElement('img');
      icon.src = fileType === 'application/pdf'
        ? 'https://imgs.mobileshopdating.com/bmimgs/contact-revamp/pdf-icon-image.png'
        : 'https://imgs.mobileshopdating.com/bmimgs/contact-revamp/file-icon-image.png'; // Show generic icon for other files
      previewElement.appendChild(icon);
    }

    // Create a remove button
    const removeButton = document.createElement('button');
    removeButton.textContent = 'x';
    removeButton.className = 'remove-button';
    removeButton.addEventListener('click', function() {
      removeFile(index);
    });

    previewElement.appendChild(removeButton);
    previewContainer.appendChild(previewElement);
  });
}
function uploadFiles() {
  const maxSize = 10 * 1024 * 1024; // 10MB in bytes
  var node = document.forms["chatform"]["node"].value;
  var ticketid = document.forms["chatform"]["ticketid"].value;
  var subform = 1;
  if(node == ""){
  subform = 2;
  $(".error-chat-message").text("Please enter your message").show();
  return;
  }
  const formData = new FormData();
  filesToUpload.forEach((file, index) => {
    if(file.size > maxSize){
      subform = 2;
      $(".error-chat-message").text("Each file must be smaller than 10MB.").show();
      return;
    }
    formData.append('attachment[]', file);
  });

  formData.append('ticketid',ticketid);
  formData.append('node',node);

  if(subform==1) {

  // Make the AJAX request
  const xhr = new XMLHttpRequest();
  xhr.open('POST', 'https://api.mobileshopdating.com/bmcrm/ajax_chatdetail.php', true);

  xhr.onload = function() {
    if (xhr.status === 200) {
      document.getElementById('node').value="";
      let msg = xhr.responseText;
      ticket_details(msg);
      filesToUpload = []; // Reset files after successful upload
      updatePreviews();   // Clear previews after upload
      $(".error-chat-message").text("").show();
    } else {
      $(".error-chat-message").text("Upload failed!").show();
      return;
    }
  };

  xhr.send(formData);
  }
}
document.getElementById('chatform').addEventListener('submit', function(event) {
  event.preventDefault();  // This stops the form from submitting
  //alert('Form submission prevented!');
});
function time_ago(time) {
switch (typeof time) {
  case 'number':
  break;
  case 'string':
  time = +new Date(time);
  break;
  case 'object':
  if (time.constructor === Date) time = time.getTime();
  break;
  default:
  time = +new Date();
}
var time_formats = [
  [60, 'seconds', 1], // 60
  [120, '1 minute ago', '1 minute from now'], // 60*2
  [3600, 'minutes', 60], // 60*60, 60
  [7200, '1 hour ago', '1 hour from now'], // 60*60*2
  [86400, 'hours', 3600], // 60*60*24, 60*60
  [172800, 'Yesterday', 'Tomorrow'], // 60*60*24*2
  [604800, 'days', 86400], // 60*60*24*7, 60*60*24
  [1209600, 'One week', 'Next week'], // 60*60*24*7*4*2
  [2419200, 'weeks', 604800], // 60*60*24*7*4, 60*60*24*7
  [4838400, 'One month', 'Next month'], // 60*60*24*7*4*2
  [29030400, 'months', 2419200], // 60*60*24*7*4*12, 60*60*24*7*4
  [58060800, 'Last year', 'Next year'], // 60*60*24*7*4*12*2
  [2903040000, 'years', 29030400], // 60*60*24*7*4*12*100, 60*60*24*7*4*12
  [5806080000, 'Last century', 'Next century'], // 60*60*24*7*4*12*100*2
  [58060800000, 'centuries', 2903040000] // 60*60*24*7*4*12*100*20, 60*60*24*7*4*12*100
];
var seconds = (+new Date() - time) / 1000,
  token = 'ago',
  list_choice = 1;

if (seconds == 0) {
  return 'Just now'
}
if (seconds < 0) {
  seconds = Math.abs(seconds);
  token = 'from now';
  list_choice = 2;
}
var i = 0,
  format;
while (format = time_formats[i++])
  if (seconds < format[0]) {
  if (typeof format[2] == 'string')
    return format[list_choice];
  else
    return Math.floor(seconds / format[2]) + ' ' + format[1] + ' ' + token;
  }
return time;
}
</script>

